def:pub Meta(data: dict[(str, any)]) -> JsxElement {
    locale = data.get("locale");
    lang = locales.get(locale as str) or locales["en"];
    title = data.get("title");
    description = data.get("description");
    image = str(data.get("image")) if data.get("image") else None;
    canonical = "https://hanspoon-31cd9.web.app/";
    `type = data.get("type") if data.get("type") else "website";
    width = (data.get("width") or 1200) if data.get("image") else None;
    height = (data.get("height") or 630) if data.get("image") else None;

    return
        <div>
            <meta name="description" content={description}/>
            {canonical and <link rel="canonical" href={canonical}/>}
            {image and <link href={image}/>}
            {image and <meta itemProp="image" content={image}/>}
            <meta property="og:site_name" content="YOUR WEB SITE"/>
            <meta property="og:title" content={title}/>
            {description and <meta property="og:description" content={description}/>}
            {canonical and <meta property="og:url" content={canonical}/>}
            <meta property="og:locale" content={locales.get(lang as str)}/>
            <meta property="og:type" content={`type}/>
            {image and <meta property="og:image" content={image}/>}
            {width and <meta property="og:image:width" content={width}/>}
            {height and <meta property="og:image:height" content={height}/>}
            <meta property="fb:pages" content="YOUR WEB SITE"/>
            {#* change type of twitter if there is no image? *#}
            <meta name="twitter:card" content="summary_large_image"/>
            <meta name="twitter:title" content={title}/>
            {description and <meta name="twitter:description" content={description}/>}
            {image and <meta name="twitter:image" content={image}/>}
