glob RESULTS_PER_PAGE = 12;

def:pub MyRecipes() -> JsxPage {
    has recipesToBeDisplayed: list[SearchRecipeItem] = [];
    has myRecipes: list[SearchRecipeItem] = [];
    has isLoading: bool = True;
    has currentPage: int = 1;

    auth = useSelector(lambda (state: RootState) -> AuthState { return state.auth; });
    authUser = auth.authUser;
    authLoading = auth.isLoading;
    router = useRouter();

    can with [authLoading, authUser] entry {
        if not authLoading and not authUser {
            router.push('/');
        }
    }

    async can with [authUser] entry {
        if authUser {
            data = await getMyRecipes(authUser);
            myRecipes = data;
            recipesToBeDisplayed = data[0:RESULTS_PER_PAGE];
            isLoading = False;
        }
    }

    can with [currentPage] entry {
        recipesToBeDisplayed = myRecipes[(currentPage - 1) * RESULTS_PER_PAGE:currentPage * RESULTS_PER_PAGE];
        window.scrollTo(0, 0);
    }

    def handle_page_change(page: int) {
        currentPage = page;
    }

    if isLoading {
        return <Loading message="Loading my recipes" showBackground={False} />;
    }

    return <>
        <Head>
            <title>My Recipes - TwoSpoon</title>
            <Meta data={{"title": "My Recipes - TwoSpoon"}} />
        </Head>
        {if len(myRecipes) == 0 {
            <EmptyPage>
                <Heading as="h2">Nothing saved</Heading>
                <p>Save recipes!</p>
            </EmptyPage>
        } else {
            <CardList results={recipesToBeDisplayed} />
            <Pagination
                limit={RESULTS_PER_PAGE}
                onClick={handle_page_change}
                currentPage={currentPage}
                totalResults={len(myRecipes)}
            />
        }}
    </>;
}

