import from "@/lib/utils" { cn }
import from "motion/react" { HTMLMotionProps, motion }

glob:pub GRADIENT_ANGLES = {"top": 0, "right": 90, "bottom": 180, "left": 270};

def:pub ProgressiveBlur(direction: str = "bottom", blurLayers: int = 8, className: str = "", blurIntensity: float = 0.25, props: dict[str, any] = None) -> JsxElement {
    props = props or {};
    layers: int = max(blurLayers, 2);
    segmentSize: float = 1.0 / (blurLayers + 1);
    angle: int = GRADIENT_ANGLES[direction] as int;

    specs: list[dict] = [];
    for i in range(layers) {
        positions: list[float] = [i * segmentSize, (i + 1) * segmentSize, (i + 2) * segmentSize, (i + 3) * segmentSize];
        stops: list[str] = [];
        for (posIndex, pos) in enumerate(positions) {
            alpha: int = 1 if (posIndex == 1 or posIndex == 2) else 0;
            stops.append(f"rgba(255, 255, 255, {alpha}) {pos * 100}%");
        }
        gradient: str = f"linear-gradient({angle}deg, {', '.join(stops)})";
        specs.append({"index": i, "gradient": gradient, "blur": f"blur({i * blurIntensity}px)"});
    }

    <div className={cn("relative", className)}>
        {[
            <motion.div
                key={spec["index"]}
                className="pointer-events-none absolute inset-0 rounded-[inherit]"
                style={{"maskImage": spec["gradient"], "WebkitMaskImage": spec["gradient"], "backdropFilter": spec["blur"]}}
                {**props}
            /> for spec in specs
        ]}
    </div>
}

import from "object-code" { hash }

glob:pub createCacheKey = None;
glob SLASHES_REGEX = "/";

def:pub defaultCacheKeyGenerator(config: any) -> any {
    url = config.url;
    method = config.method;
    baseURL = config.baseURL;
    headers = config.headers;
    data = config.data;
    params = config.params;

    _baseURL = baseURL.removeprefix(SLASHES_REGEX).removesuffix(SLASHES_REGEX) if baseURL else baseURL;
    _url = url.removeprefix(SLASHES_REGEX).removesuffix(SLASHES_REGEX) if url else url;
    _method = method.lower() if method else method;

    return hash({
        url: _url,
        method: _method,
        baseURL: _baseURL,
        headers: headers,
        data: data,
        params: params
    });
}

